import pathlib,re,subprocess
p=re.compile(r'(?i)AWS_ACCESS_KEY_ID|AWS_SECRET_ACCESS_KEY|(?:api[_-]?key|(?:github|hf|huggingface|wandb)[_-]?token|password)\\s*[=:]|AKIA[0-9A-Z]{16}|hf_[A-Za-z0-9]{20,}|gh[pousr]_[A-Za-z0-9]{20,}|github_pat_')
