   print(f'{f}:{i} '+re.sub(r'(?<=[=:]).*',' [VALUE REDACTED]',re.sub(r'(?:hf_|gh[pousr]_|github_pat_|AKIA)[A-Za-z0-9_]+','[TOKEN REDACTED]',l))[:180])
